#include "engine/editor_authoring.hpp"
#include "engine/editor_ai.hpp"
#include "engine/editor_animation.hpp"
#include "engine/editor_prefab.hpp"
#include "engine/editor_cinematic.hpp"
#include "engine/effect_archive.hpp"
#include "engine/skeletal_mesh_component.hpp"
#include <iostream>
#include <filesystem>
#include <fstream>
using namespace engine;
namespace {
void require(bool v,const char* s){if(!v)throw std::runtime_error(s);}
}
int main(int argc,char** argv){try{
    Scene scene;auto& actor=scene.spawn<Actor>("Performer");auto skeleton=std::make_shared<Skeleton>();skeleton->joints={{"Root",-1,{}}};skeleton->bindings={{},{0,Mat4::identity()}};skeleton->clips={{"Idle",1,2,{{},{}}}};skeleton->validate();auto mesh=std::make_shared<Mesh>(*Mesh::cube());mesh->skeleton=skeleton;auto& sk=actor.addComponent<SkeletalMeshComponent>("Character",mesh);scene.synchronize();
    GuiSystem gui;EditorSession editor(scene);auto panel=std::make_unique<EditorAuthoringPanel>(gui,scene,editor);panel->setVisible(true);gui.layout({1000,800});
    auto find=[&](const std::string& name){gui.layout({1000,800});for(const auto& n:gui.accessibilityNodes())if(n.name==name&&!n.disabled&&n.keyboardFocusable)return n.id;throw std::runtime_error("Missing control: "+name);};
    auto click=[&](const std::string& name){require(gui.activateWidget(find(name)),"Activation failed");panel->update();};
    auto field=[&](const std::string& name,const std::string& value){if(!gui.focusWidget(find(name))){for(const auto& n:gui.accessibilityNodes())if(n.name==name)std::cerr<<name<<" bounds "<<n.bounds.x<<","<<n.bounds.y<<","<<n.bounds.width<<","<<n.bounds.height<<" clip "<<n.clippedBounds.width<<","<<n.clippedBounds.height<<"\n";throw std::runtime_error("Focus failed: "+name);}gui.editText(value,value.size(),value.size());};
    auto encoded=[&]{return panel->saveDocument();};
    click("Create terrain");require(editor.terrainActor(),"Terrain creation failed");const auto flat=SceneArchive::save(scene,{},{},{},{},aiControllerCodecs());click("Stamp terrain");require(SceneArchive::save(scene,{},{},{},{},aiControllerCodecs())!=flat,"Terrain did not change");click("Scene undo");require(SceneArchive::save(scene,{},{},{},{},aiControllerCodecs())==flat,"Terrain history failed");
    click("AI");click("Add AI state");field("AI transition to state index","1");click("Add AI transition");auto graphBytes=encoded();auto graph=StateMachineArchive::load(std::string(reinterpret_cast<const char*>(graphBytes.data()),graphBytes.size()));require(graph->data().states.size()==2&&graph->data().transitions.size()==1,"AI graph edits failed");editor.select(actor.savedId());click("Assign AI graph to selection");require(editor.selectedAiController(),"AI graph assignment failed");click("Document undo");require(encoded()!=graphBytes,"Independent AI undo failed");click("Document redo");require(encoded()==graphBytes,"Independent AI redo failed");
    panel->markSaved();const auto valid=encoded();try{panel->openDocument(std::array{std::byte{1}},true);throw 1;}catch(const std::exception&){}require(encoded()==valid,"Bad file replaced graph");
    click("Animation");editor.select(sk.savedId());click("Capture selected animation library");field("Clip label","Authored idle");click("Apply animation clip");click("Add animation state for clip");click("Add animation transition");const auto anim=encoded();auto library=AnimationLibraryArchive::load(anim);require(library->data().clips[0].label=="Authored idle"&&library->data().controller.transitions.size()==1,"Animation authoring failed");click("Assign animation library to selection");require(bool(editor.selectedSkeletalMesh()->animation().controller()),"Animation assignment failed");
    click("Prefab");auto& prop=scene.spawn<Actor>("Prop");prop.addComponent<MeshComponent>("Mesh",Mesh::cube());scene.synchronize();editor.select(prop.savedId());click("Capture selected prefab");field("Prefab definition node index","1");field("Prefab node position X","2");click("Apply prefab node position");click("Place linked prefab");require(editor.selectedPrefabRoot(),"Prefab placement failed");const auto prefab=PrefabAssetArchive::load(encoded());require(prefab->definition().children()[0]->transform.position.x==2,"Prefab definition not edited");field("Prefab node position X","3");click("Apply prefab node position");click("Publish prefab to scene instances");require(editor.selectedPrefabRoot()->children()[0]->transform.position.x==3,"Prefab instance did not update");
    editor.select(prop.savedId());click("Use selected prefab as nested source");click("Nest source in prefab");require(PrefabAssetArchive::load(encoded())->dependencies().size()==1,"Nested prefab composition failed");click("Document undo");
    click("FX");field("FX spawn rate","7");click("Apply FX emitter");const auto effect=encoded();require(EffectArchive::load(effect)->emitters[0].definition->spawnRate==7,"FX authoring failed");field("FX lifetime minimum","-1");click("Apply FX emitter");require(encoded()==effect,"Invalid FX replaced valid asset");click("Place FX");require(editor.selectedEffect(),"FX placement failed");
    click("Cinematic");editor.select(actor.savedId());click("Add cinematic track for selection");field("Key / sample time seconds","4");click("Record selected pose at time");const auto cine=encoded();auto sequence=CinematicSequenceArchive::load(std::string(reinterpret_cast<const char*>(cine.data()),cine.size()));require(sequence->data().tracks[0].keys.size()==3,"Cinematic key authoring failed");click("Document undo");require(encoded()!=cine,"Cinematic history failed");click("Document redo");require(encoded()==cine,"Cinematic redo failed");
    const auto before=SceneArchive::save(scene,{},{},{},{},aiControllerCodecs());require(gui.activateWidget(find("Remove cinematic track")),"Cannot queue command");panel->update(false);panel->update(true);require(encoded()==cine&&SceneArchive::save(scene,{},{},{},{},aiControllerCodecs())==before,"Play gate published queued edits");
    if(argc>1){std::filesystem::path out(argv[1]);std::filesystem::create_directories(out);auto write=[&](std::string name,const auto& b){std::ofstream f(out/name,std::ios::binary);f.write(reinterpret_cast<const char*>(b.data()),b.size());};write("fixture.weanim",anim);write("fixture.weai",graphBytes);write("fixture.weprefab",PrefabAssetArchive::save(prefab));write("fixture.wefx",effect);write("fixture.wecin",cine);}
    if(argc>2){std::filesystem::path out(argv[2]);auto read=[&](std::string n){std::ifstream f(out/n,std::ios::binary);if(!f)throw std::runtime_error("Missing exchanged file "+n);std::string s((std::istreambuf_iterator<char>(f)),{});const auto b=std::as_bytes(std::span(s.data(),s.size()));return std::vector<std::byte>(b.begin(),b.end());};for(const std::string backend:{"webgpu","webgl2"}){auto b=read(backend+".weanim");require(AnimationLibraryArchive::load(b)->data().clips[0].label=="Browser authored idle","Browser animation exchange failed");b=read(backend+".wefx");require(EffectArchive::load(b)->emitters[0].definition->spawnRate==9,"Browser FX exchange failed");b=read(backend+".weprefab");require(bool(PrefabAssetArchive::load(b)),"Browser prefab exchange failed");b=read(backend+".weai");require(StateMachineArchive::load(std::string(reinterpret_cast<const char*>(b.data()),b.size()))->data().states.size()==2,"Browser AI exchange failed");b=read(backend+".wecin");require(CinematicSequenceArchive::load(std::string(reinterpret_cast<const char*>(b.data()),b.size()))->data().tracks[0].keys.size()==3,"Browser cinematic exchange failed");}std::cout<<"Browser WebGPU/WebGL2 documents loaded and verified by native archives\n";}
    panel.reset();for(const auto& n:gui.accessibilityNodes())require(n.name!="Create terrain","Destroyed panel remained accessible");
    std::cout<<"Shared authoring GUI: terrain, animation, AI, nested prefab, FX, cinematic, files, independent history, invalid state and Play gate passed\n";
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
